package cn.zhuatech.apimanagement.deep;import cn.zhuatech.apimanagement.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/apim") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/apis")ApiResponse<?> api(@Valid @RequestBody DeepDomainService.ApiRequest r){return ApiResponse.ok(s.register(r));}@PostMapping("/apis/{id}/submit")ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.ok(s.submit(id));}@PostMapping("/apps")ApiResponse<?> app(@Valid @RequestBody DeepDomainService.AppRequest r){return ApiResponse.ok(s.createApp(r));}@PostMapping("/subscriptions")ApiResponse<?> sub(@Valid @RequestBody DeepDomainService.SubscriptionRequest r){return ApiResponse.ok(s.subscribe(r));}@PostMapping("/apis/{id}/metrics")ApiResponse<?> metric(@PathVariable Long id,@Valid @RequestBody DeepDomainService.MetricRequest r){return ApiResponse.ok(s.recordMetric(id,r));}}
